<template>
    <div id="App" v-if="hasMiniGame || hasMinigameGif">
        <Hacking v-if="hasMiniGame && minigameType === 'hacking'" ref="hacking" :miniGameRespond="miniGameRespond" :NameResource="NameResource" :close="close"/>
        <Thermite v-if="hasMiniGame && minigameType === 'thermite'" ref="thermite" :miniGameRespond="miniGameRespond" :NameResource="NameResource" :close="close"/>
        <Lockpick v-if="hasMiniGame && minigameType === 'lockpick'" ref="lockpick" :miniGameRespond="miniGameRespond" :NameResource="NameResource" :close="close"/>

        <div v-if="hasMinigameGif" class="illegal-gif">
            <img :src="'voltlab/' + minigameGif" alt="">
        </div>
    </div>
</template>

<script>

import axios from 'axios';

import Hacking from './minigames/Hacking';
import Thermite from './minigames/Thermite';
import Lockpick from './minigames/Lockpick';

export default {
    components: {
        Hacking,
        Thermite,
        Lockpick,
    },

    data: function(){
        return({
            hasMinigameGif: false,
            minigameGif: '',
            hasMiniGame: false,
            minigameType: '',
            NameResource: ["st_minigames"],
        })
    },

    methods: {
        receiveLua: function(event) {
            if(!event || !event.data) return;
            const lua = event.data;

            if(lua.init) {
                this.NameResource = lua.NameResource;
            }

            if(lua.openMinigameGif) {
                this.hasMinigameGif = true;
                this.minigameGif = lua.minigameGif;
            }

            if(lua.closeMinigameGif) {
                this.hasMinigameGif = false;
                this.minigameGif = '';
            }

            if(lua.openMinigame) {
                if(!lua.minigameType) return;

                this.hasMiniGame = true;
                this.minigameType = lua.minigameType;

                this.$nextTick(() => {
                    if (this.minigameType === 'hacking' && this.$refs.hacking) {
                        this.$refs.hacking.StartMiniGame(lua.hackingType, lua.hackingTimeout, lua.hackingInterval);
                    }

                    if (this.minigameType === 'thermite' && this.$refs.thermite) {
                        this.$refs.thermite.StartMiniGame(lua.mode, lua.speed);
                    }

                    if (this.minigameType === 'lockpick' && this.$refs.lockpick) {
                        this.$refs.lockpick.StartMiniGame(lua.corrects, lua.timeMultiplier);
                    }
                });
            }
        },

        miniGameRespond: function(respond) {
            const NameResource = this.NameResource[0];
            axios.post(`https://${NameResource}/miniGameRespond`, {
                type: this.minigameType,
                respond: respond,
            }).catch(function (error) {
                console.log(error + ' : Error at miniGameRespond');
            });

            this.close();
        },

        close: function() {
            this.opened = false;

            this.hasMiniGame = false;
            this.minigameType = '';

            const NameResource = this.NameResource[0];
            axios.post(`https://${NameResource}/close`).catch(function (error) {
                console.log(error + ' : Error at close');
            });
        },

        keyPress: function(event) {
            const key = event.key;
            
            if(key == "Escape"){
                this.close();
            }
        },
    },

    created: function(){
        window.addEventListener('message', this.receiveLua);  
        window.addEventListener('keydown', this.keyPress);
    },
    
    destroyed: function(){
        window.removeEventListener('message', this.receiveLua);
        window.removeEventListener('keydown', this.keyPress);
    },
}
</script>

<style>
@keyframes glitch {
    0% { text-shadow: 2px 2px #ff00ff, -2px -2px #00ffff; }
    25% { text-shadow: -2px 2px #ff00ff, 2px -2px #00ffff; }
    50% { text-shadow: -2px -2px #ff00ff, 2px 2px #00ffff; }
    75% { text-shadow: 2px -2px #ff00ff, -2px 2px #00ffff; }
    100% { text-shadow: -2px -2px #ff00ff, 2px 2px #00ffff; }
}

@keyframes flicker {
    0%, 100% { opacity: 1; }
    50% { opacity: 0.8; }
}

* {
	padding: 0; 
	margin: 0; 
	box-sizing: border-box; 
    font-family: Roboto;
    overflow: hidden;
}

button:hover {
    cursor: pointer;
}

.illegal-gif {
    position: absolute;
    width: 100%;
    height: 100%;
    display: flex;
    justify-content: center;
    align-items: center;
}

.illegal-gif img {
    top: 0;
    left: 0;
    width: 100%;
    min-height: 100%;
    position: fixed;
}
</style>